//! # The guest-ingress gate: may a guest name this RM control or allocation class at all?
//!
//! Default deny. A control word or an `hClass` that arrives from the guest crosses into kayfabe
//! only if [`crate::ingress_generated`] has a row for it at the guest's driver tag and that row's
//! verdict there is [`Verdict::Allow`]. Everything else is refused: by NAME with a [`Refusal`] when
//! the id has a row, and as [`Denial::NotOnAllowlist`] when it has none.
//!
//! ## Where the data comes from
//!
//! The rows are generated by `tools/api_boundaries/ingress_policy.py` from three inputs and
//! nothing else (design: `docs/design/V3_GUEST_INGRESS_TABLE.md`):
//!
//! 1. NVIDIA's open-gpu-kernel-modules at every driver-matrix tag: each control's
//!    `RMCTRL_FLAGS` as exported by its class, and each class's allocation privilege in
//!    `resource_list.h` (`tools/api_boundaries/ingress_facts.tsv` holds the facts);
//! 2. what kayfabe serves: the ids and names its own code uses
//!    (`tools/api_boundaries/served.json`; this gate is not read, so it cannot vouch for itself);
//! 3. kayfabe's own rows (`tools/api_boundaries/ingress_rules.tsv`): ids that reach kayfabe only
//!    because Mode 2's transport is GSP RPC ([`Basis::Mode2Rpc`]), ids seen on a real host
//!    stream ([`Basis::Empirical`]), and kayfabe's judgements ([`Judgement`]).
//!
//! The rule: a served control is admitted where its tag exports it `NON_PRIVILEGED` and not
//! `PRIVILEGED`, `INTERNAL` or test-only; a served class where `resource_list.h` gives it
//! `RS_FLAGS_ALLOC_NON_PRIVILEGED` (or it is a client root); a rule row overrides that verdict for
//! its tags. A new driver branch needs only its ogkm tag and a rerun of the generator.
//!
//! ## What the gate does not do
//!
//! Admission is necessary, never sufficient: every admitted id still needs a consumer that
//! decides its shape (`DriverAbiTable::control_params` / `alloc_params`, the channel plane, the
//! display link). An admitted id without one is refused there. The gate exists so that writing
//! a new decoder can never by itself widen what a guest may name. The channel link
//! (`kf_rm::chanlink`), which sits before the object seat in the served chain, asks the gate about
//! every control before any of its arms; `crates/kf-rm/tests/ingress_parity.rs` pins that order and
//! that every control it claims has an admitting row.

use crate::DriverVersion;
use crate::ingress_generated as g;
use kf_arch::ids::{ClassId, ControlCmd};

/// Bit 15 of a control word: RM's "legacy GSS" control family, serviced by GSP firmware
/// (`ogkm-580: src/nvidia/interface/deprecated/rmapi_deprecated.h:41`, tested at
/// `rmapi_deprecated_control.c:97`). The gate gives these no special treatment; the constant is
/// here for the served-chain links that answer some of them (`kf_rm::inittables`).
pub const RM_GSS_LEGACY_MASK: u32 = 0x0000_8000;

/// Why an id is admitted.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum Basis {
    /// The tag's own export flags make it callable by an unprivileged client (controls), or
    /// `resource_list.h` marks the class `RS_FLAGS_ALLOC_NON_PRIVILEGED`.
    OgkmNonPrivileged,
    /// A client root (`NV01_ROOT*`): RM allocates it through `serverAllocClient`, which applies
    /// no resource privilege check (`ogkm-580: libraries/resserv/src/rs_server.c:728-766`).
    OgkmClientRoot,
    /// kayfabe's own row: reaches kayfabe only because in Mode 2 the guest's KERNEL RM talks to
    /// kayfabe as its GSP. Every such row has a consumer that decides its params shape.
    Mode2Rpc,
    /// kayfabe's own row: seen on a real host RM ioctl stream and served by kayfabe.
    Empirical,
}

/// A refusal decision kayfabe made where ogkm's flags alone would admit the id. Each one is
/// explained, with its evidence, in `tools/api_boundaries/ingress_rules.tsv`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum Judgement {
    /// Reads, writes or locates raw GPU registers of the shared GPU.
    RegisterAccess,
    /// Hardware performance-monitor streaming.
    Profiler,
    /// SM-level debugger trap control (MMU debug mode, suspend, resume).
    SmDebugger,
    /// Memory named by the caller's own address, or privileged video memory.
    CallerMemory,
    /// The board's I2C buses, which this device does not have.
    NoBoardBus,
    /// Host- or board-wide state (power, ECC, PCIe, NVLink, BIOS, scheduling, caches, fabric).
    HostScope,
    /// A display-engine query or setting; the emulated display answers display state itself.
    DisplayEngine,
    /// Answered or refused by kayfabe's served chain before the gate; nothing needs it admitted.
    AnsweredInChain,
    /// An engine class kayfabe has no validated guest constructor for.
    EngineNotModelled,
    /// kayfabe's serving of it is validated only from a later tag.
    NotValidatedAtTag,
}

/// Why an id with a row is refused at a tag.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum Refusal {
    /// The tag exports it `PRIVILEGED` (admin) or the class needs `RS_FLAGS_ALLOC_PRIVILEGED`.
    Privileged,
    /// Kernel clients only: no visibility flag on the control, or `RS_FLAGS_ALLOC_KERNEL_PRIVILEGED`.
    KernelOnly,
    /// `RMCTRL_FLAGS_INTERNAL`: RM's own kernel-to-physical traffic.
    Internal,
    /// `RMCTRL_FLAGS_RM_TEST_ONLY_CODE`.
    TestOnly,
    /// A class `resource_list.h` lists with no allocation privilege flag (RM refuses it too).
    NoPrivilegeFlag,
    /// The tag does not export the control or list the class (renumbered, added later, removed).
    AbsentAtTag,
    /// kayfabe's judgement.
    Judgement(Judgement),
}

/// One row's decision at a span of tags.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Verdict {
    /// Admitted.
    Allow(Basis),
    /// Refused by name.
    Refuse(Refusal),
}

/// A span of consecutive [`crate::ingress_generated::TAGS`] (indices `first..=last`) with one name
/// and one verdict.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Run {
    /// First tag index of the span.
    pub first: u8,
    /// Last tag index of the span (inclusive).
    pub last: u8,
    /// NVIDIA's name for the id at these tags (empty where no tag names it).
    pub name: &'static str,
    /// The decision.
    pub verdict: Verdict,
}

/// Every decision about one id, across the tags.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct IngressRow {
    /// The control word or `hClass`.
    pub id: u32,
    /// `false` for an id kayfabe answers itself and never sends to a host
    /// (`tools/api_boundaries/answered_never_forwarded.txt`; classes are never forwarded as such).
    pub forwarded: bool,
    /// The spans, ascending and disjoint.
    pub runs: &'static [Run],
}

impl IngressRow {
    /// The span covering tag index `tag`, if any.
    #[must_use]
    pub fn at(&self, tag: u8) -> Option<&'static Run> {
        self.runs.iter().find(|r| r.first <= tag && tag <= r.last)
    }
}

/// Why a control or class did not pass.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Denial {
    /// The id has a row and is refused at this tag, by name and reason.
    Refused {
        /// NVIDIA's name for it.
        name: &'static str,
        /// Why.
        why: Refusal,
    },
    /// No row: kayfabe does not serve the id (or no ogkm tag knows it). The default.
    NotOnAllowlist,
}

/// The gate's answer for a control.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[must_use]
pub enum ControlPermit {
    /// Admitted.
    Admitted {
        /// NVIDIA's name for it.
        name: &'static str,
        /// Why.
        basis: Basis,
    },
    /// Refused.
    Denied(Denial),
}

impl ControlPermit {
    /// Did it pass?
    #[must_use]
    pub const fn is_permitted(self) -> bool {
        matches!(self, ControlPermit::Admitted { .. })
    }
}

/// The gate's answer for an allocation class.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[must_use]
pub enum AllocPermit {
    /// Admitted.
    Admitted {
        /// NVIDIA's name for it.
        name: &'static str,
        /// Why.
        basis: Basis,
    },
    /// Refused.
    Denied(Denial),
}

impl AllocPermit {
    /// Did it pass?
    #[must_use]
    pub const fn is_permitted(self) -> bool {
        matches!(self, AllocPermit::Admitted { .. })
    }
}

/// The gate at one driver tag.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CapabilityTable {
    tag: u8,
}

/// One gate per [`crate::ingress_generated::TAGS`] entry, in the same order.
static GATES: [CapabilityTable; g::TAGS.len()] = {
    let mut out = [CapabilityTable { tag: 0 }; g::TAGS.len()];
    let mut i = 0;
    while i < out.len() {
        out[i] = CapabilityTable { tag: i as u8 };
        i += 1;
    }
    out
};

const _: () = assert!(g::TAGS.len() <= u8::MAX as usize, "tag index is a u8");

fn decide(rows: &'static [IngressRow], id: u32, tag: u8) -> Result<(&'static str, Basis), Denial> {
    let Ok(i) = rows.binary_search_by_key(&id, |r| r.id) else {
        return Err(Denial::NotOnAllowlist);
    };
    match rows[i].at(tag) {
        Some(Run {
            name,
            verdict: Verdict::Allow(basis),
            ..
        }) => Ok((name, *basis)),
        Some(Run {
            name,
            verdict: Verdict::Refuse(why),
            ..
        }) => Err(Denial::Refused { name, why: *why }),
        None => Err(Denial::NotOnAllowlist),
    }
}

impl CapabilityTable {
    /// The gate for exactly `version`, or `None` when the table has no such tag. There is no
    /// nearest-tag fallback: flags move between tags.
    #[must_use]
    pub fn for_version(version: DriverVersion) -> Option<&'static CapabilityTable> {
        g::TAGS.binary_search(&version).ok().map(|i| &GATES[i])
    }

    /// Every gate, in tag order.
    pub fn all() -> impl Iterator<Item = &'static CapabilityTable> {
        GATES.iter()
    }

    /// The driver tag this gate decides for.
    #[must_use]
    pub fn version(&self) -> DriverVersion {
        g::TAGS[usize::from(self.tag)]
    }

    /// May the guest issue this control?
    pub fn control(&self, cmd: ControlCmd) -> ControlPermit {
        match decide(g::CONTROLS, cmd.0, self.tag) {
            Ok((name, basis)) => ControlPermit::Admitted { name, basis },
            Err(d) => ControlPermit::Denied(d),
        }
    }

    /// May the guest allocate this class?
    pub fn alloc_class(&self, class: ClassId) -> AllocPermit {
        match decide(g::CLASSES, class.0, self.tag) {
            Ok((name, basis)) => AllocPermit::Admitted { name, basis },
            Err(d) => AllocPermit::Denied(d),
        }
    }

    /// Every control row with its span at this tag (admitted and refused).
    pub fn control_rows(&self) -> impl Iterator<Item = (&'static IngressRow, &'static Run)> + '_ {
        let t = self.tag;
        g::CONTROLS
            .iter()
            .filter_map(move |r| r.at(t).map(|run| (r, run)))
    }

    /// Every class row with its span at this tag (admitted and refused).
    pub fn class_rows(&self) -> impl Iterator<Item = (&'static IngressRow, &'static Run)> + '_ {
        let t = self.tag;
        g::CLASSES
            .iter()
            .filter_map(move |r| r.at(t).map(|run| (r, run)))
    }

    /// The controls admitted at this tag.
    pub fn admitted_controls(&self) -> impl Iterator<Item = u32> + '_ {
        self.control_rows()
            .filter(|(_, run)| matches!(run.verdict, Verdict::Allow(_)))
            .map(|(r, _)| r.id)
    }

    /// The classes admitted at this tag.
    pub fn admitted_classes(&self) -> impl Iterator<Item = u32> + '_ {
        self.class_rows()
            .filter(|(_, run)| matches!(run.verdict, Verdict::Allow(_)))
            .map(|(r, _)| r.id)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn every_row() -> impl Iterator<Item = &'static IngressRow> {
        g::CONTROLS.iter().chain(g::CLASSES.iter())
    }

    #[test]
    fn rows_are_sorted_unique_and_their_runs_are_ascending_disjoint_and_in_range() {
        for rows in [g::CONTROLS, g::CLASSES] {
            assert!(rows.windows(2).all(|w| w[0].id < w[1].id));
        }
        let n = u8::try_from(g::TAGS.len()).unwrap();
        for r in every_row() {
            assert!(!r.runs.is_empty(), "{:#x}", r.id);
            for w in r.runs.windows(2) {
                assert!(w[0].last < w[1].first, "{:#x}", r.id);
            }
            assert!(
                r.runs.iter().all(|x| x.first <= x.last && x.last < n),
                "{:#x}",
                r.id
            );
        }
    }

    #[test]
    fn the_gate_tags_are_the_driver_matrix_tags() {
        assert_eq!(g::TAGS, crate::generated::matrix::MEASURED);
        assert!(g::TAGS.windows(2).all(|w| w[0] < w[1]));
    }

    #[test]
    fn an_unlisted_id_is_refused_by_default_at_every_tag() {
        for t in CapabilityTable::all() {
            assert_eq!(
                t.control(ControlCmd(0xdead_beef)),
                ControlPermit::Denied(Denial::NotOnAllowlist)
            );
            assert_eq!(
                t.alloc_class(ClassId(0xfee1)),
                AllocPermit::Denied(Denial::NotOnAllowlist)
            );
        }
    }

    #[test]
    fn a_version_between_tags_has_no_gate() {
        let v = DriverVersion {
            major: 580,
            minor: 65,
            patch: 7,
        };
        assert!(CapabilityTable::for_version(v).is_none());
        for t in CapabilityTable::all() {
            assert_eq!(CapabilityTable::for_version(t.version()), Some(t));
        }
    }

    #[test]
    fn the_permit_is_the_rows_verdict() {
        for t in CapabilityTable::all() {
            for (r, run) in t.control_rows() {
                let p = t.control(ControlCmd(r.id));
                match run.verdict {
                    Verdict::Allow(basis) => assert_eq!(
                        p,
                        ControlPermit::Admitted {
                            name: run.name,
                            basis
                        }
                    ),
                    Verdict::Refuse(why) => assert_eq!(
                        p,
                        ControlPermit::Denied(Denial::Refused {
                            name: run.name,
                            why
                        })
                    ),
                }
            }
            for (r, run) in t.class_rows() {
                assert_eq!(
                    t.alloc_class(ClassId(r.id)).is_permitted(),
                    matches!(run.verdict, Verdict::Allow(_))
                );
            }
        }
    }

    /// The GSS-legacy bit is not a pass: an unlisted bit-15 control is refused like any other.
    #[test]
    fn gss_legacy_controls_get_no_rule_pass() {
        for t in CapabilityTable::all() {
            for cmd in [0x2080_8000_u32, 0x0000_ffff, 0x2081_0000, 0xdead_8001] {
                assert!(!t.control(ControlCmd(cmd)).is_permitted(), "{cmd:#x}");
            }
        }
    }
}
